function (vars) {
	var g = new GridWidget(vars.element, vars.dataSource);
	g.groupable = false;
	g.searchable = false;
	g.filterable = false;
	g.pageable = false;
	g.scrollable = true;
	g.editable = false;
	g.exports = true;
	
	g.columns = [
		{
			field: "CreatedOn",
			format: "{0:" + type.dateFormat + "}",
			title: "[resource_shortdisplayname[CreatedOn]]",
			description: "[resource_description[CreatedOn]]",
			type: "date",
			width: 80
		},
		{
			field: "Key",
			title: "[resource_shortdisplayname[key]]",
			description: "[resource_description[key]]",
			width: 100
		},
        {
			field: "Name",
			title: "[resource_shortdisplayname[Name]]",
			description: "[resource_description[Name]]"
		}
	];
	
	g.detailTemplate = "<div name='container'></div>";
	g.detailExpand = async function (e) {
		var report = JSON.parse(this.dataItem(e.masterRow).Value);
		var container = $(e.detailRow).find("div[name=container]");
		container.html("");
		await vars.buildDetails(container, report);
	};

	return g;
}
